import java.io.BufferedInputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    private static final class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ' && c != -1) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = Integer.parseInt(fs.next());
        int m = Integer.parseInt(fs.next());
        int k = Integer.parseInt(fs.next());

        char[] password = fs.next().toCharArray();
        char[][] choices = new char[m][];
        for (int i = 0; i < m; i++) {
            choices[i] = fs.next().toCharArray();
            Arrays.sort(choices[i]);
        }

        long p = fs.nextLong();
        long[] suffixWays = new long[m];
        if (m > 0) {
            suffixWays[m - 1] = 1;
            for (int i = m - 2; i >= 0; i--) {
                suffixWays[i] = Math.min(p, suffixWays[i + 1] * k);
            }
        }

        long rank = p - 1;
        int index = 0;
        for (int i = 0; i < n; i++) {
            if (password[i] == '#') {
                long choiceIndex = rank / suffixWays[index];
                rank %= suffixWays[index];
                password[i] = choices[index][(int) choiceIndex];
                index++;
            }
        }

        System.out.println(new String(password));
    }
}
